#########
  # GDSC ETL is performed in two steps: shell script to ETL data into postgres
  # and then additional transformations with SQL in postGIS (if needed).
  ####

  #########
  # Step 1 - bash script (pseudo code)
  ####

  # create directory structure and move into it
  mkdir -p /data/us_2023_annual_aqi_by_county/download -p /data/us_2023_annual_aqi_by_county/etl
  chmod -R 777 /data/us_2023_annual_aqi_by_county
  cd /data/us_2023_annual_aqi_by_county

  # set update flag based on last update and update frequency
  do_update=0 if date() < last_update + update_frequency else do_update = 1

  # download if update flag is set:
  if do_update == 1 then
  curl -o download/us_2023_annual_aqi_by_county.zip 'https://aqs.epa.gov/aqsweb/airdata/annual_aqi_by_county_2023.zip' 2>&1

  # unzip to download directory if update flag is set
  if do_update == 1 then
  unzip -o download/us_2023_annual_aqi_by_county.zip -d download && rm download/us_2023_annual_aqi_by_county.zip 2>&1

  # remove spaces, periods, and leading numerical digits in column headers (if needed)
    if (head -n 1 download/annual_aqi_by_county_2023.csv | grep -qE '\s|\.|\"[0-9]'); then
      sed -i '1s/ /_/g; 1s/\.//g; 1s/\"\([0-9]\)/\"n\1/g' download/annual_aqi_by_county_2023.csv 2>&1
    fi

  # load into postGIS with:
  ogr2ogr -lco GEOMETRY_NAME=geom -f PostgreSQL PG:"<postgres connection>" download/annual_aqi_by_county_2023.csv -nlt multipolygon -nln us_2023_annual_aqi_by_county
  echo success: annual_aqi_by_county_2023.csv loaded with ogr2ogr

  # rename data table to temp
  psql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gdsc-postgis-node-umkidxlh8gbelhv5 -c "
  ALTER SEQUENCE IF EXISTS us_2023_annual_aqi_by_county_ogc_fid_seq RENAME TO temp_ogc_fid_seq;
  ALTER INDEX IF EXISTS us_2023_annual_aqi_by_county_geom_geom_idx RENAME TO temp_geom_idx;
  ALTER TABLE IF EXISTS us_2023_annual_aqi_by_county RENAME CONSTRAINT us_2023_annual_aqi_by_county_pkey TO temp_pkey;
  ALTER TABLE us_2023_annual_aqi_by_county RENAME TO temp;"

  # Create copy of geom dependency
  pg_dump -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gdsc-postgis-node-1mvqjl62x1cy6jze -t us_2023_county_tl | sed 's/us_2023_county_tl/us_2023_annual_aqi_by_county/g' | psql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gdsc-postgis-node-umkidxlh8gbelhv5

  # create copy of the FIPS lookup table
  pg_dump -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gdsc-postgis-node-7tema7aedsvsnv0h -t us_2020_census_county_fips | psql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gdsc-postgis-node-umkidxlh8gbelhv5

  # join as per custom parameters
  psql -d $POSTGRES_DB -U $POSTGRES_USER -p $POSTGRES_PORT -h gdsc-postgis-node-umkidxlh8gbelhv5 -c "
  ALTER TABLE temp ADD COLUMN geoid varchar;
  UPDATE temp SET geoid = CONCAT(us_2020_census_county_fips.state,us_2020_census_county_fips.county)
    FROM us_2020_census_county_fips
    WHERE position(temp.state in us_2020_census_county_fips.state_name)>0
    AND position(temp.county in us_2020_census_county_fips.county_name)>0;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN state varchar;
  UPDATE us_2023_annual_aqi_by_county SET state=temp.state::varchar
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN county varchar;
  UPDATE us_2023_annual_aqi_by_county SET county=temp.county::varchar
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN year varchar;
  UPDATE us_2023_annual_aqi_by_county SET year=temp.year::varchar
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_with_aqi int4;
  UPDATE us_2023_annual_aqi_by_county SET days_with_aqi=temp.days_with_aqi::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN good_days int4;
  UPDATE us_2023_annual_aqi_by_county SET good_days=temp.good_days::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN moderate_days int4;
  UPDATE us_2023_annual_aqi_by_county SET moderate_days=temp.moderate_days::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN unhealthy_for_sensitive_groups_days int4;
  UPDATE us_2023_annual_aqi_by_county SET unhealthy_for_sensitive_groups_days=temp.unhealthy_for_sensitive_groups_days::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN unhealthy_days int4;
  UPDATE us_2023_annual_aqi_by_county SET unhealthy_days=temp.unhealthy_days::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN very_unhealthy_days int4;
  UPDATE us_2023_annual_aqi_by_county SET very_unhealthy_days=temp.very_unhealthy_days::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN hazardous_days int4;
  UPDATE us_2023_annual_aqi_by_county SET hazardous_days=temp.hazardous_days::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN max_aqi int4;
  UPDATE us_2023_annual_aqi_by_county SET max_aqi=temp.max_aqi::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN n90th_percentile_aqi int4;
  UPDATE us_2023_annual_aqi_by_county SET n90th_percentile_aqi=temp.n90th_percentile_aqi::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN median_aqi int4;
  UPDATE us_2023_annual_aqi_by_county SET median_aqi=temp.median_aqi::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_co int4;
  UPDATE us_2023_annual_aqi_by_county SET days_co=temp.days_co::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_no2 int4;
  UPDATE us_2023_annual_aqi_by_county SET days_no2=temp.days_no2::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_ozone int4;
  UPDATE us_2023_annual_aqi_by_county SET days_ozone=temp.days_ozone::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_pm25 int4;
  UPDATE us_2023_annual_aqi_by_county SET days_pm25=temp.days_pm25::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  ALTER TABLE us_2023_annual_aqi_by_county ADD COLUMN days_pm10 int4;
  UPDATE us_2023_annual_aqi_by_county SET days_pm10=temp.days_pm10::int4
    FROM temp
    WHERE us_2023_annual_aqi_by_county.geoid = temp.geoid;

  DROP table temp;
  "
